                    prepare_script.push_str("actual_uuid=$(blkid -s UUID -o value \"$expected_device\" 2>/dev/null || true)\n");
                    prepare_script.push_str("if [ \"$actual_filesystem\" != \"$expected_filesystem\" ] || [ \"$actual_uuid\" != \"$expected_uuid\" ]; then\n");
