        let second = InrouDurableEgressCheckpoint::load_or_create(
            &state_dir,
            "portal",
            11,
            18,
            "1.0.0",
            1,
            &Hash::new(b"placement-1"),
            &ALICE_ID,
            None,
        )?;
        let replacement = InrouDurableEgressCheckpoint::load_or_create(
            &state_dir,
            "portal",
            11,
            17,
            "1.0.0",
            1,
            &Hash::new(b"placement-2"),
            &ALICE_ID,
            None,
        )?;
